package com.johnny.hotel.workforce;
import com.johnny.hotel.entity.SysUser;import com.johnny.hotel.organization.Department;import com.johnny.hotel.workforce.WorkforceModels.*;
import org.apache.ibatis.annotations.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Mapper public interface WorkforceMapper {
 @Select("SELECT * FROM sys_user WHERE id=#{id} FOR UPDATE") SysUser lockUser(Long id);
 @Select("SELECT * FROM department WHERE id=#{id} FOR UPDATE") Department lockDepartment(Long id);
 @Select("SELECT * FROM workforce_approval_config WHERE id=1 FOR UPDATE") ApprovalConfig lockApprovalConfig();
 @Insert("INSERT INTO workforce_approval_config(id,hr_department_id,updated_by) VALUES(1,#{hrDepartmentId},#{updatedBy}) ON DUPLICATE KEY UPDATE hr_department_id=VALUES(hr_department_id),updated_by=VALUES(updated_by)") int saveApprovalConfig(ApprovalConfig config);
 @Select("SELECT u.id FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.id JOIN sys_role r ON r.id=ur.role_id WHERE u.status=1 AND r.role_code=#{role} ORDER BY u.id FOR UPDATE") List<Long> activeUsersByRole(String role);
 @Insert("INSERT INTO attendance_session(employee_id,status,effective_check_in,effective_check_out) VALUES(#{employeeId},#{status},#{effectiveCheckIn},#{effectiveCheckOut})") @Options(useGeneratedKeys=true,keyProperty="id") int insertSession(AttendanceSession s);
 @Select("SELECT * FROM attendance_session WHERE employee_id=#{employee} AND status=0 FOR UPDATE") AttendanceSession openForUpdate(Long employee);
 @Select("SELECT * FROM attendance_session WHERE employee_id=#{employee} AND status=0") AttendanceSession open(Long employee);
 @Select("SELECT * FROM attendance_session WHERE id=#{id} FOR UPDATE") AttendanceSession lockSession(Long id);
 @Insert("INSERT INTO attendance_punch(employee_id,session_id,punch_type,punched_at,ip_address,source,user_agent,operator_user_id,request_key) VALUES(#{employeeId},#{sessionId},#{punchType},#{punchedAt},#{ipAddress},#{source},#{userAgent},#{operatorUserId},#{requestKey})") @Options(useGeneratedKeys=true,keyProperty="id") int insertPunch(AttendancePunch p);
 @Select("SELECT * FROM attendance_punch WHERE employee_id=#{employee} AND request_key=#{key}") AttendancePunch punchByKey(@Param("employee")Long employee,@Param("key")String key);
 @Update("UPDATE attendance_session SET check_in_punch_id=#{punch} WHERE id=#{session} AND check_in_punch_id IS NULL") int attachIn(@Param("session")Long session,@Param("punch")Long punch);
 @Update("UPDATE attendance_session SET status=1,effective_check_out=#{at},check_out_punch_id=#{punch} WHERE id=#{session} AND status=0") int closeSession(@Param("session")Long session,@Param("at")LocalDateTime at,@Param("punch")Long punch);
 @Select("<script>SELECT s.*,TIMESTAMPDIFF(SECOND,s.effective_check_in,s.effective_check_out) worked_seconds,CASE WHEN EXISTS(SELECT 1 FROM employee_leave_request l WHERE l.employee_id=s.employee_id AND l.status=2 AND l.start_at&lt;COALESCE(s.effective_check_out,s.effective_check_in) AND l.end_at&gt;s.effective_check_in) THEN 'ATTENDANCE_ON_APPROVED_LEAVE' END exception_code FROM attendance_session s WHERE s.employee_id=#{employee}<if test='from!=null'> AND s.effective_check_in&gt;=#{from}</if><if test='to!=null'> AND s.effective_check_in&lt;#{to}</if> ORDER BY s.effective_check_in DESC,s.id DESC LIMIT #{offset},#{size}</script>") List<AttendanceSession> attendancePage(@Param("employee")Long employee,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM attendance_session s WHERE s.employee_id=#{employee}<if test='from!=null'> AND s.effective_check_in&gt;=#{from}</if><if test='to!=null'> AND s.effective_check_in&lt;#{to}</if></script>") long attendanceCount(@Param("employee")Long employee,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to);
 @Select("<script>SELECT s.*,TIMESTAMPDIFF(SECOND,s.effective_check_in,s.effective_check_out) worked_seconds,CASE WHEN EXISTS(SELECT 1 FROM employee_leave_request l WHERE l.employee_id=s.employee_id AND l.status=2 AND l.start_at&lt;COALESCE(s.effective_check_out,s.effective_check_in) AND l.end_at&gt;s.effective_check_in) THEN 'ATTENDANCE_ON_APPROVED_LEAVE' WHEN s.status=0 AND s.effective_check_in&lt;#{anomalyBefore} THEN 'MISSING_CHECKOUT' END exception_code FROM attendance_session s JOIN sys_user u ON u.id=s.employee_id <where><if test='employee!=null'>s.employee_id=#{employee}</if><if test='department!=null'>AND u.department_id=#{department}</if><if test='from!=null'>AND s.effective_check_in&gt;=#{from}</if><if test='to!=null'>AND s.effective_check_in&lt;#{to}</if></where> ORDER BY s.effective_check_in DESC,s.id DESC LIMIT #{offset},#{size}</script>") List<AttendanceSession> attendanceAdminPage(@Param("employee")Long employee,@Param("department")Long department,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to,@Param("anomalyBefore")LocalDateTime anomalyBefore,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM attendance_session s JOIN sys_user u ON u.id=s.employee_id <where><if test='employee!=null'>s.employee_id=#{employee}</if><if test='department!=null'>AND u.department_id=#{department}</if><if test='from!=null'>AND s.effective_check_in&gt;=#{from}</if><if test='to!=null'>AND s.effective_check_in&lt;#{to}</if></where></script>") long attendanceAdminCount(@Param("employee")Long employee,@Param("department")Long department,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to);
 @Select("<script>SELECT s.*,TIMESTAMPDIFF(SECOND,s.effective_check_in,s.effective_check_out) worked_seconds,CASE WHEN EXISTS(SELECT 1 FROM employee_leave_request l WHERE l.employee_id=s.employee_id AND l.status=2 AND l.start_at&lt;COALESCE(s.effective_check_out,s.effective_check_in) AND l.end_at&gt;s.effective_check_in) THEN 'ATTENDANCE_ON_APPROVED_LEAVE' ELSE 'MISSING_CHECKOUT' END exception_code FROM attendance_session s JOIN sys_user u ON u.id=s.employee_id WHERE (s.status=0 AND s.effective_check_in&lt;#{anomalyBefore} OR EXISTS(SELECT 1 FROM employee_leave_request l WHERE l.employee_id=s.employee_id AND l.status=2 AND l.start_at&lt;COALESCE(s.effective_check_out,s.effective_check_in) AND l.end_at&gt;s.effective_check_in))<if test='department!=null'> AND u.department_id=#{department}</if> ORDER BY s.effective_check_in DESC,s.id DESC LIMIT #{offset},#{size}</script>") List<AttendanceSession> anomalyPage(@Param("department")Long department,@Param("anomalyBefore")LocalDateTime anomalyBefore,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM attendance_session s JOIN sys_user u ON u.id=s.employee_id WHERE (s.status=0 AND s.effective_check_in&lt;#{anomalyBefore} OR EXISTS(SELECT 1 FROM employee_leave_request l WHERE l.employee_id=s.employee_id AND l.status=2 AND l.start_at&lt;COALESCE(s.effective_check_out,s.effective_check_in) AND l.end_at&gt;s.effective_check_in))<if test='department!=null'> AND u.department_id=#{department}</if></script>") long anomalyCount(@Param("department")Long department,@Param("anomalyBefore")LocalDateTime anomalyBefore);
 @Insert("INSERT INTO attendance_correction_request(employee_id,department_id_snapshot,approver_user_id_snapshot,approval_route,session_id,correction_type,requested_check_in,requested_check_out,reason,status,request_key,requested_at) VALUES(#{employeeId},#{departmentIdSnapshot},#{approverUserIdSnapshot},#{approvalRoute},#{sessionId},#{correctionType},#{requestedCheckIn},#{requestedCheckOut},#{reason},0,#{requestKey},#{requestedAt})") @Options(useGeneratedKeys=true,keyProperty="id") int insertCorrection(AttendanceCorrection c);
 @Select("SELECT * FROM attendance_correction_request WHERE employee_id=#{employee} AND request_key=#{key}") AttendanceCorrection correctionByKey(@Param("employee")Long employee,@Param("key")String key);
 @Select("SELECT * FROM attendance_correction_request WHERE id=#{id} FOR UPDATE") AttendanceCorrection lockCorrection(Long id);
 @Update("UPDATE attendance_correction_request SET task_id=#{task} WHERE id=#{id} AND task_id IS NULL") int attachCorrectionTask(@Param("id")Long id,@Param("task")Long task);
 @Update("UPDATE attendance_correction_request SET status=#{status},decision_note=#{note},decided_by=#{actor},decided_at=#{now} WHERE id=#{id} AND status=0") int decideCorrection(@Param("id")Long id,@Param("status")int status,@Param("note")String note,@Param("actor")Long actor,@Param("now")LocalDateTime now);
 @Update("UPDATE attendance_correction_request SET approver_user_id_snapshot=#{approver} WHERE id=#{id} AND status=0") int reassignCorrection(@Param("id")Long id,@Param("approver")Long approver);
 @Update("UPDATE attendance_correction_request SET approver_user_id_snapshot=#{approver} WHERE task_id=#{task} AND status=0 AND approver_user_id_snapshot IS NULL") int resolveCorrectionApprover(@Param("task")Long task,@Param("approver")Long approver);
 @Select("SELECT * FROM attendance_correction_request WHERE task_id=#{task} FOR UPDATE") AttendanceCorrection correctionByTask(Long task);
 @Insert("INSERT INTO attendance_correction_fact(request_id,session_id,effective_check_in,effective_check_out,approved_by,approved_at) VALUES(#{requestId},#{sessionId},#{effectiveCheckIn},#{effectiveCheckOut},#{approvedBy},#{approvedAt})") int insertCorrectionFact(CorrectionFact f);
 @Update("UPDATE attendance_session SET effective_check_in=#{inAt},effective_check_out=#{outAt},status=CASE WHEN #{outAt} IS NULL THEN 0 ELSE 1 END WHERE id=#{id}") int applyCorrection(@Param("id")Long id,@Param("inAt")LocalDateTime inAt,@Param("outAt")LocalDateTime outAt);
 @Select("<script>SELECT * FROM attendance_correction_request <where><if test='employee!=null'>employee_id=#{employee}</if><if test='approver!=null'>AND approver_user_id_snapshot=#{approver}</if><if test='status!=null'>AND status=#{status}</if></where> ORDER BY id DESC LIMIT #{offset},#{size}</script>") List<AttendanceCorrection> correctionPage(@Param("employee")Long employee,@Param("approver")Long approver,@Param("status")Integer status,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM attendance_correction_request <where><if test='employee!=null'>employee_id=#{employee}</if><if test='approver!=null'>AND approver_user_id_snapshot=#{approver}</if><if test='status!=null'>AND status=#{status}</if></where></script>") long correctionCount(@Param("employee")Long employee,@Param("approver")Long approver,@Param("status")Integer status);
 @Select("SELECT c.* FROM attendance_correction_request c WHERE c.status=0 AND (c.approver_user_id_snapshot=#{actor} OR c.approver_user_id_snapshot IS NULL AND EXISTS(SELECT 1 FROM task_eligible_role e JOIN sys_role r ON r.role_code=e.role_code JOIN sys_user_role ur ON ur.role_id=r.id WHERE e.task_id=c.task_id AND ur.user_id=#{actor})) ORDER BY c.id DESC LIMIT #{offset},#{size}") List<AttendanceCorrection> pendingCorrections(@Param("actor")Long actor,@Param("offset")int offset,@Param("size")int size);
 @Select("SELECT COUNT(*) FROM attendance_correction_request c WHERE c.status=0 AND (c.approver_user_id_snapshot=#{actor} OR c.approver_user_id_snapshot IS NULL AND EXISTS(SELECT 1 FROM task_eligible_role e JOIN sys_role r ON r.role_code=e.role_code JOIN sys_user_role ur ON ur.role_id=r.id WHERE e.task_id=c.task_id AND ur.user_id=#{actor}))") long pendingCorrectionCount(Long actor);

 @Insert("INSERT INTO leave_type(code,name,unit,paid_treatment,requires_balance,requires_attachment,active,description,created_by,updated_by) VALUES(#{code},#{name},#{unit},#{paidTreatment},#{requiresBalance},#{requiresAttachment},#{active},#{description},#{createdBy},#{updatedBy})") @Options(useGeneratedKeys=true,keyProperty="id") int insertLeaveType(LeaveType t);
 @Update("UPDATE leave_type SET name=#{name},unit=#{unit},paid_treatment=#{paidTreatment},requires_balance=#{requiresBalance},requires_attachment=#{requiresAttachment},active=#{active},description=#{description},updated_by=#{updatedBy} WHERE id=#{id}") int updateLeaveType(LeaveType t);
 @Select("SELECT * FROM leave_type WHERE id=#{id}") LeaveType leaveType(Long id);
 @Select("SELECT * FROM leave_type WHERE id=#{id} FOR UPDATE") LeaveType lockLeaveType(Long id);
 @Select("SELECT * FROM leave_type ORDER BY id DESC LIMIT #{offset},#{size}") List<LeaveType> leaveTypes(@Param("offset")int offset,@Param("size")int size);
 @Select("SELECT COUNT(*) FROM leave_type") long leaveTypeCount();
 @Insert("INSERT INTO leave_allocation(employee_id,leave_type_id,period_start,period_end,amount,reason,request_key,created_by) VALUES(#{employeeId},#{leaveTypeId},#{periodStart},#{periodEnd},#{amount},#{reason},#{requestKey},#{createdBy})") @Options(useGeneratedKeys=true,keyProperty="id") int insertAllocation(LeaveAllocation a);
 @Select("SELECT * FROM leave_allocation WHERE created_by=#{actor} AND request_key=#{key}") LeaveAllocation allocationByKey(@Param("actor")Long actor,@Param("key")String key);
 @Select("SELECT COALESCE(SUM(amount),0) FROM leave_allocation WHERE employee_id=#{employee} AND leave_type_id=#{type} AND period_start <= #{end} AND period_end >= #{start}") BigDecimal allocated(@Param("employee")Long employee,@Param("type")Long type,@Param("start")LocalDate start,@Param("end")LocalDate end);
 @Select("SELECT MIN(period_start) FROM leave_allocation WHERE employee_id=#{employee} AND leave_type_id=#{type} AND period_start <= #{end} AND period_end >= #{start}") LocalDate allocationStart(@Param("employee")Long employee,@Param("type")Long type,@Param("start")LocalDate start,@Param("end")LocalDate end);
 @Select("SELECT MAX(period_end) FROM leave_allocation WHERE employee_id=#{employee} AND leave_type_id=#{type} AND period_start <= #{end} AND period_end >= #{start}") LocalDate allocationEnd(@Param("employee")Long employee,@Param("type")Long type,@Param("start")LocalDate start,@Param("end")LocalDate end);
 @Select("SELECT COALESCE(SUM(requested_amount),0) FROM employee_leave_request WHERE employee_id=#{employee} AND leave_type_id=#{type} AND status=#{status} AND start_at < #{end} AND end_at > #{start}") BigDecimal leaveAmount(@Param("employee")Long employee,@Param("type")Long type,@Param("status")int status,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);
 @Insert("INSERT INTO employee_leave_request(employee_id,leave_type_id,start_at,end_at,requested_amount,reason,attachment_reference,status,request_key) VALUES(#{employeeId},#{leaveTypeId},#{startAt},#{endAt},#{requestedAmount},#{reason},#{attachmentReference},0,#{requestKey})") @Options(useGeneratedKeys=true,keyProperty="id") int insertLeave(LeaveRequest r);
 @Select("SELECT * FROM employee_leave_request WHERE employee_id=#{employee} AND request_key=#{key}") LeaveRequest leaveByKey(@Param("employee")Long employee,@Param("key")String key);
 @Select("SELECT * FROM employee_leave_request WHERE id=#{id}") LeaveRequest leave(Long id);
 @Select("SELECT * FROM employee_leave_request WHERE id=#{id} FOR UPDATE") LeaveRequest lockLeave(Long id);
 @Update("UPDATE employee_leave_request SET leave_type_id=#{leaveTypeId},start_at=#{startAt},end_at=#{endAt},requested_amount=#{requestedAmount},reason=#{reason},attachment_reference=#{attachmentReference} WHERE id=#{id} AND employee_id=#{employeeId} AND status=0") int updateDraft(LeaveRequest r);
 @Select("SELECT COUNT(*) FROM employee_leave_request WHERE employee_id=#{employee} AND id != #{id} AND status IN (1,2) AND start_at < #{end} AND end_at > #{start} FOR UPDATE") int overlap(@Param("employee")Long employee,@Param("id")Long id,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end);
 @Update("UPDATE employee_leave_request SET status=1,department_id_snapshot=#{department},approver_user_id_snapshot=#{approver},approval_route=#{route},task_id=#{task},submitted_at=#{now} WHERE id=#{id} AND status=0") int submitLeave(@Param("id")Long id,@Param("department")Long department,@Param("approver")Long approver,@Param("route")String route,@Param("task")Long task,@Param("now")LocalDateTime now);
 @Update("UPDATE employee_leave_request SET status=#{status},decision_note=#{note},decided_by=#{actor},decided_at=#{now} WHERE id=#{id} AND status=1") int decideLeave(@Param("id")Long id,@Param("status")int status,@Param("note")String note,@Param("actor")Long actor,@Param("now")LocalDateTime now);
 @Update("UPDATE employee_leave_request SET approver_user_id_snapshot=#{approver} WHERE id=#{id} AND status=1") int reassignLeave(@Param("id")Long id,@Param("approver")Long approver);
 @Update("UPDATE employee_leave_request SET approver_user_id_snapshot=#{approver} WHERE task_id=#{task} AND status=1 AND approver_user_id_snapshot IS NULL") int resolveLeaveApprover(@Param("task")Long task,@Param("approver")Long approver);
 @Select("SELECT * FROM employee_leave_request WHERE task_id=#{task} FOR UPDATE") LeaveRequest leaveByTask(Long task);
 @Update("UPDATE employee_leave_request SET status=4,cancel_reason=#{reason},cancelled_at=#{now} WHERE id=#{id} AND employee_id=#{employee} AND status=#{expected}") int cancelLeave(@Param("id")Long id,@Param("employee")Long employee,@Param("expected")int expected,@Param("reason")String reason,@Param("now")LocalDateTime now);
 @Select("<script>SELECT * FROM employee_leave_request <where><if test='employee!=null'>employee_id=#{employee}</if><if test='approver!=null'>AND approver_user_id_snapshot=#{approver}</if><if test='status!=null'>AND status=#{status}</if></where> ORDER BY id DESC LIMIT #{offset},#{size}</script>") List<LeaveRequest> leavePage(@Param("employee")Long employee,@Param("approver")Long approver,@Param("status")Integer status,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM employee_leave_request <where><if test='employee!=null'>employee_id=#{employee}</if><if test='approver!=null'>AND approver_user_id_snapshot=#{approver}</if><if test='status!=null'>AND status=#{status}</if></where></script>") long leaveCount(@Param("employee")Long employee,@Param("approver")Long approver,@Param("status")Integer status);
 @Select("SELECT l.* FROM employee_leave_request l WHERE l.status=1 AND (l.approver_user_id_snapshot=#{actor} OR l.approver_user_id_snapshot IS NULL AND EXISTS(SELECT 1 FROM task_eligible_role e JOIN sys_role r ON r.role_code=e.role_code JOIN sys_user_role ur ON ur.role_id=r.id WHERE e.task_id=l.task_id AND ur.user_id=#{actor})) ORDER BY l.id DESC LIMIT #{offset},#{size}") List<LeaveRequest> pendingLeaves(@Param("actor")Long actor,@Param("offset")int offset,@Param("size")int size);
 @Select("SELECT COUNT(*) FROM employee_leave_request l WHERE l.status=1 AND (l.approver_user_id_snapshot=#{actor} OR l.approver_user_id_snapshot IS NULL AND EXISTS(SELECT 1 FROM task_eligible_role e JOIN sys_role r ON r.role_code=e.role_code JOIN sys_user_role ur ON ur.role_id=r.id WHERE e.task_id=l.task_id AND ur.user_id=#{actor}))") long pendingLeaveCount(Long actor);
 @Insert("INSERT INTO leave_action_history(leave_request_id,action_type,actor_user_id,detail) VALUES(#{id},#{action},#{actor},#{detail})") int leaveHistory(@Param("id")Long id,@Param("action")String action,@Param("actor")Long actor,@Param("detail")String detail);
}
